    if (obh->length != jp2c->length || strncmp(obh->type, "jp2c", 4) != 0) {
        fprintf(FCGI_stderr, "Reference jp2c header in prxy box not correct\n");
    }
    pos += obh->headlen;
    opj_free(obh);

    ni = fetch_DBox1byte(prxy, pos);
    if (ni != 1) {
        fprintf(FCGI_stderr, "Multiple indexes not supported\n");
        opj_free(prxy);
        return OPJ_FALSE;
