    mhix = gene_mhixbox(mhix_box);
    opj_free(mhix_box);

    sizmkidx = search_markeridx(0xff51, mhix);
    set_SIZmkrdata(sizmkidx, codestream, &(jp2idx->SIZ));

    codmkidx = search_markeridx(0xff52, mhix);
    set_CODmkrdata(codmkidx, codestream, &(jp2idx->COD));

    delete_mhixbox(&mhix);

    return OPJ_TRUE;
}

